// Shared by every Code node. scripts/build.mjs pastes this file in front of
// route.js, render.js and notify.js, because n8n Code nodes cannot import.

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Everything that came from a person or the database goes through esc()
// before it is put into a message, because messages are sent as HTML.
const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// Days travel as "2026-11-14" in data and as "20261114" inside buttons. They
// are plain calendar dates in the studio's time zone; Postgres owns the clock.
const asDate = (iso) => new Date(`${iso}T00:00:00Z`);
const addDays = (iso, count) => {
  const date = asDate(iso);
  date.setUTCDate(date.getUTCDate() + count);
  return date.toISOString().slice(0, 10);
};
const dayName = (iso) => {
  const date = asDate(iso);
  return `${WEEKDAYS[date.getUTCDay()]} ${date.getUTCDate()} ${MONTHS[date.getUTCMonth()]}`;
};
const dayLabel = (iso, today) => {
  if (iso === today) return `${dayName(iso)} (today)`;
  if (iso === addDays(today, 1)) return `${dayName(iso)} (tomorrow)`;
  return dayName(iso);
};
const packDay = (iso) => iso.replace(/-/g, '');
const unpackDay = (packed) => {
  if (!/^\d{8}$/.test(packed ?? '')) return null;
  const iso = `${packed.slice(0, 4)}-${packed.slice(4, 6)}-${packed.slice(6, 8)}`;
  const date = asDate(iso);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === iso ? iso : null;
};
const packTime = (hhmm) => hhmm.replace(':', '');
const unpackTime = (packed) => {
  if (!/^\d{4}$/.test(packed ?? '')) return null;
  const hours = Number(packed.slice(0, 2));
  const minutes = Number(packed.slice(2, 4));
  return hours < 24 && minutes < 60 ? `${packed.slice(0, 2)}:${packed.slice(2, 4)}` : null;
};

const button = (text, data) => ({ text, callback_data: data });
const rowsOf = (items, perRow) => {
  const rows = [];
  for (let i = 0; i < items.length; i += perRow) rows.push(items.slice(i, i + perRow));
  return rows;
};

// A booking or a move in progress is not stored anywhere. Each button carries
// every choice made so far, for example "b:c2:r1:d20261114:t0900":
//   c class type   r room (0 = ask)   d day   t start time
//   p trainer (0 = ask)   n weeks to repeat   w week shown in the day picker
// So there is no session to expire or to get out of step with the screen, and
// "Back" is simply the same data with the last choice left out. Telegram
// allows 64 bytes per button; the longest of these is under 50.
const STEP_KEYS = ['c', 'r', 'd', 't', 'p', 'n', 'w'];
const wizard = (base, steps) =>
  [base]
    .concat(
      STEP_KEYS.filter((key) => steps[key] !== undefined && steps[key] !== null).map(
        (key) => `${key}${steps[key]}`,
      ),
    )
    .join(':');
const without = (steps, ...keys) =>
  Object.fromEntries(Object.entries(steps).filter(([key]) => !keys.includes(key)));
const readSteps = (parts) => {
  const steps = {};
  for (const part of parts) {
    const key = part[0];
    const value = part.slice(1);
    if (!STEP_KEYS.includes(key)) continue;
    if (key === 'd' && unpackDay(value)) steps.d = value;
    else if (key === 't' && unpackTime(value)) steps.t = value;
    else if ('crpnw'.includes(key) && /^\d{1,9}$/.test(value)) steps[key] = String(Number(value));
  }
  return steps;
};
// The "Route" Code node: turn one Telegram update into the name of a branch,
// the screen to draw and the request for that branch's database function.
// It decides where to go, never whether it is allowed: Postgres checks that.

const COMMANDS = {
  start: 'h',
  menu: 'h',
  help: 'help',
  schedule: 's',
  today: 's',
  book: 'b',
  my: 'm',
  calendar: 'cal',
  people: 'pl',
  rooms: 'ro',
  classtypes: 'cl',
};

function route(update, begin) {
  if (!begin || begin.skip) return null;
  const tap = update.callback_query;
  const message = tap ? tap.message : update.message;
  if (!message || !message.chat) return null;

  const me = begin.me;
  const reply = {
    chat_id: message.chat.id,
    message_id: tap ? message.message_id : null,
    callback_id: tap ? tap.id : null,
  };
  const go = (branch, screen, req = {}, extra = {}) => ({
    branch,
    screen,
    req: { tg: me.tg, ...req },
    reply,
    ...extra,
  });

  if (me.status !== 'active') return go('home', me.status);

  let action;
  if (tap) {
    action = String(tap.data || 'h');
  } else {
    const text = String(message.text || '').trim();
    if (text.startsWith('/')) {
      action = COMMANDS[text.slice(1).split(/[\s@]/)[0].toLowerCase()] || 'unknown';
    } else if (begin.awaiting && text) {
      return go('manage', 'manage', { op: 'input', text: text.slice(0, 200) });
    } else {
      return go('home', 'home', {}, { hint: 'unknown' });
    }
  }

  const parts = action.split(':');
  const head = parts[0];
  const id = (index) => (/^\d{1,15}$/.test(parts[index] || '') ? Number(parts[index]) : null);

  switch (head) {
    case 'h':
      return go('home', 'home');
    case 'help':
      return go('home', 'help');

    case 's': {
      const day = unpackDay(parts[1]);
      return go('schedule', parts[2] === 'm' ? 'day_classes' : 'schedule', day ? { day } : {});
    }

    // Booking: "b:..." shows the next question, "B:..." commits.
    case 'b':
    case 'B': {
      const steps = readSteps(parts.slice(1));
      const wiz = { base: 'b', steps };
      const req = {};
      if (steps.c) req.class = Number(steps.c);
      if (steps.r && steps.r !== '0') req.room = Number(steps.r);
      if (steps.d) req.day = unpackDay(steps.d);
      if (steps.t) req.time = unpackTime(steps.t);
      if (steps.p && steps.p !== '0') req.trainer = Number(steps.p);
      if (steps.w) req.week = Number(steps.w);
      const complete = req.class && req.room && req.day && req.time;
      if (head === 'B' && complete) {
        return go('book', 'booked', { ...req, repeat: steps.n ? Number(steps.n) : 1 }, { wiz });
      }
      if (steps.p === '0') return go('options', 'book_trainer', req, { wiz });
      if (!req.class) return go('options', 'book_class', req, { wiz });
      if (!req.room) return go('options', 'book_room', req, { wiz });
      if (!req.day) return go('days', 'book_day', req, { wiz });
      if (!req.time) return go('slots', 'book_time', req, { wiz });
      return go('preview', 'book_confirm', req, { wiz });
    }

    // Moving a class: "e:<id>:..." asks, "E:<id>:..." commits.
    case 'e':
    case 'E': {
      const booking = id(1);
      if (!booking) return go('home', 'home', {}, { hint: 'unknown' });
      const steps = without(readSteps(parts.slice(2)), 'c', 'p', 'n');
      const wiz = { base: `e:${booking}`, steps };
      const req = { booking };
      if (steps.r && steps.r !== '0') req.room = Number(steps.r);
      if (steps.d) req.day = unpackDay(steps.d);
      if (steps.t) req.time = unpackTime(steps.t);
      if (steps.w) req.week = Number(steps.w);
      if (head === 'E' && req.day && req.time) return go('reschedule', 'moved', req, { wiz });
      if (steps.r === '0') return go('options', 'move_room', { booking }, { wiz });
      if (!req.day) return go('days', 'move_day', req, { wiz });
      if (!req.time) return go('slots', 'move_time', req, { wiz });
      return go('preview', 'move_confirm', req, { wiz });
    }

    case 'm':
      return go('bookings', 'mine', { page: id(1) || 0 });
    case 'v':
      return id(1) ? go('booking', 'view', { id: id(1) }) : go('home', 'home');
    case 'x':
      return id(1) ? go('booking', 'cancel_confirm', { id: id(1) }) : go('home', 'home');
    case 'X':
      return id(1)
        ? go('cancel', 'cancelled', { id: id(1), following: parts[2] === 'f' })
        : go('home', 'home');

    case 'pl':
      return go('people', 'people', { op: 'list' });
    case 'pv':
      return go('people', 'person', { op: 'view', id: id(1) });
    case 'ps':
      return go('people', 'person', { op: 'set', id: id(1), action: parts[2] });

    case 'ro':
      return go('manage', 'manage', { op: 'rooms' });
    case 'rt':
      return go('manage', 'manage', { op: 'room_toggle', id: id(1) });
    case 'rn':
      return go('manage', 'ask', { op: 'ask', awaiting: 'room_new' });
    case 'rr':
      return go('manage', 'ask', { op: 'ask', awaiting: 'room_rename', id: id(1) });
    case 'cl':
      return go('manage', 'manage', { op: 'classes' });
    case 'ct':
      return go('manage', 'manage', { op: 'class_toggle', id: id(1) });
    case 'cn':
      return go('manage', 'ask', { op: 'ask', awaiting: 'class_new' });

    case 'cal':
      return go('calendar', 'calendar');
    default:
      return go('home', 'home', {}, { hint: 'unknown' });
  }
}

const routed = route($('Telegram Trigger').first().json, $input.first().json.data);
// Nothing to do for a repeated update or a group chat: the run ends here.
return routed ? [{ json: routed }] : [];

